import React from 'react';
import { Form, Input, Button, Typography, Space, message, Switch } from 'antd';
import { MinusCircleOutlined, PlusOutlined } from '@ant-design/icons';
import { updateAbout, createAbout } from '../../services/api';

const { TextArea } = Input;
const { Title } = Typography;

const AboutForm = ({ initialValues, onSuccess }) => {
  const [form] = Form.useForm();
  const isEditing = Boolean(initialValues?.id);

  React.useEffect(() => {
    form.resetFields();
    if (initialValues) {
      form.setFieldsValue(initialValues);
    }
  }, [initialValues, form]);

  const onFinish = async (values) => {
    try {
      // Convert characteristics array to JSON string before sending to backend
      const dataToSubmit = {
        ...values,
        characteristics: JSON.stringify(values.characteristics)
      };
      
      if (isEditing) {
        await updateAbout(initialValues.id, dataToSubmit);
        message.success('About content updated successfully');
      } else {
        await createAbout(dataToSubmit);
        message.success('About content created successfully');
      }
      onSuccess();
    } catch (error) {
      console.error('Error:', error);
      message.error(`Failed to ${isEditing ? 'update' : 'create'} about content: ${error.message}`);
    }
  };

  return (
    <div style={{ maxWidth: 800, margin: '0 auto' }}>
      <Space direction="vertical" size="large" style={{ width: '100%' }}>
        <Title level={4}>{isEditing ? 'Edit About Content' : 'Create About Content'}</Title>
        <Form
          form={form}
          layout="vertical"
          onFinish={onFinish}
          initialValues={initialValues || { characteristics: [{ value: '' }] }}
        >
          <Form.Item
            name="title"
            label="Title"
            rules={[{ required: true, message: 'Please enter title' }]}
          >
            <Input placeholder="Enter title" />
          </Form.Item>

          <Form.Item
            name="subtitle"
            label="Subtitle"
            rules={[{ required: true, message: 'Please enter subtitle' }]}
          >
            <TextArea 
              rows={6} 
              placeholder="Enter subtitle"
              style={{ resize: 'vertical' }}
            />
          </Form.Item>
          <Form.Item
            name="whatis"
            label="What is"
            rules={[{ required: true, message: 'Please enter what is' }]}
          >
            <TextArea 
              rows={6} 
              placeholder="Enter what is"
              style={{ resize: 'vertical' }}
            />
          </Form.Item>
          <Form.List
            name="characteristics"
            initialValue={[{ value: '' }]}
          >
            {(fields, { add, remove }) => (
              <>
                <Form.Item label="Characteristics">
                  {fields.map(({ key, name, ...restField }, index) => (
                    <Space key={key} style={{ display: 'flex', marginBottom: 8 }} align="baseline">
                      <Form.Item
                        {...restField}
                        name={[name, 'value']}
                        rules={[{ required: true, message: 'Please enter characteristic' }]}
                      >
                        <Input placeholder="Enter a characteristic" />
                      </Form.Item>
                      {fields.length > 1 && (
                        <MinusCircleOutlined onClick={() => remove(name)} />
                      )}
                    </Space>
                  ))}
                </Form.Item>
                <Form.Item>
                  <Button
                    type="dashed"
                    onClick={() => add()}
                    block
                    icon={<PlusOutlined />}
                  >
                    Add Characteristic
                  </Button>
                </Form.Item>
              </>
            )}
          </Form.List>

          <Form.Item
            name="organization"
            label="Organization"
          >
            <TextArea rows={4} placeholder="Enter organization details" />
          </Form.Item>

         
          <Form.Item
            name="director"
            label="Director"
          >
            <Input placeholder="Enter director name" />
          </Form.Item>
          <Form.Item
            name="deputy_director"
            label="Deputy Director"
          >
            <Input placeholder="Enter deputy director name" />
          </Form.Item>


          <Form.Item
            name="assistant"
            label="Assistant"
          >
            <Input placeholder="Enter assistant name" />
          </Form.Item>
          <Form.Item
            name="coordinator"
            label="Coordinator"
          >
            <Input placeholder="Enter coordinator name" />
          </Form.Item>

          <Form.Item
            name="isActive"
            label="Active"
            valuePropName="checked"
          >
            <Switch />
          </Form.Item>

          <Form.Item>
            <Button type="primary" htmlType="submit" size="large">
              {isEditing ? 'Update Content' : 'Create Content'}
            </Button>
          </Form.Item>
        </Form>
      </Space>
    </div>
  );
};

export default AboutForm;
