import React, { useState, useEffect } from 'react';
import { Card, message } from 'antd';
import AboutForm from '../components/about/AboutForm';
import { getAboutContent } from '../services/api';

const AboutPage = () => {
  const [content, setContent] = useState(null);
  const [loading, setLoading] = useState(false);

  const fetchAboutContent = async () => {
    setLoading(true);
    try {
      const data = await getAboutContent();
      console.log('About content response:', data);
      if (!data) {
        setContent(null);
        return;
      }
      
      // Process the data to parse characteristics if it's a JSON string
      const processData = (item) => {
        if (item && typeof item.characteristics === 'string') {
          try {
            item.characteristics = JSON.parse(item.characteristics);
          } catch (e) {
            console.error('Error parsing characteristics:', e);
            // If parsing fails, set as empty array
            item.characteristics = [];
          }
        }
        return item;
      };
      
      if (!Array.isArray(data)) {
        setContent(processData(data));
        return;
      }
      setContent(data.length > 0 ? processData(data[0]) : null);
    } catch (error) {
      console.error('Failed to fetch about content:', error);
      message.error(`Failed to fetch about content: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAboutContent();
  }, []);

  const handleSuccess = () => {
    fetchAboutContent();
    message.success('About content saved successfully');
  };

  return (
    <Card
      title="About Content"
      loading={loading}
    >
      <AboutForm
        initialValues={content}
        onSuccess={handleSuccess}
      />
    </Card>
  );
};

export default AboutPage;
