import React, { useState, useEffect, forwardRef, useImperativeHandle } from 'react';
import { getSliderItems, deleteSliderItem } from '../../services/api';
import { Table, Button, Space, Image, message, Typography } from 'antd';
import { EditOutlined, DeleteOutlined } from '@ant-design/icons';
import { useWindowSize } from '../../hooks/useWindowSize';

const SliderList = forwardRef(function SliderList({ onEdit }, ref) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const { width } = useWindowSize();

  const fetchItems = async () => {
    setLoading(true);
    try {
      const data = await getSliderItems();
      setItems(data);
    } catch (error) {
      message.error('Failed to fetch slider items');
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchItems();
  }, []);

  useImperativeHandle(ref, () => ({
    refresh: fetchItems
  }));

  const handleDelete = async (id) => {
    try {
      await deleteSliderItem(id);
      message.success('Slider item deleted successfully');
      fetchItems();
    } catch (error) {
      message.error('Failed to delete slider item');
    }
  };

  const getColumns = () => {
    const baseColumns = [
      {
        title: 'Image',
        dataIndex: 'imageUrl',
        key: 'imageUrl',
        render: (imageUrl) => (
          <Image
            src={imageUrl}
            alt="Slider"
            width={width < 768 ? 100 : 200}
            height={width < 768 ? 50 : 100}
            style={{ objectFit: 'cover' }}
          />
        ),
      },
      {
        title: 'Title',
        dataIndex: 'title',
        key: 'title',
        ellipsis: true,
      },
      {
        title: 'Order',
        dataIndex: 'order',
        key: 'order',
        sorter: (a, b) => a.order - b.order,
        width: 80,
      },
      {
        title: 'Actions',
        key: 'actions',
        width: width < 768 ? 120 : 200,
        render: (_, record) => (
          <Space>
            <Button
              type="primary"
              icon={<EditOutlined />}
              onClick={() => onEdit(record)}
              size={width < 768 ? 'small' : 'middle'}
            >
              {width >= 768 && 'Edit'}
            </Button>
            <Button
              type="primary"
              danger
              icon={<DeleteOutlined />}
              onClick={() => handleDelete(record.id)}
              size={width < 768 ? 'small' : 'middle'}
            >
              {width >= 768 && 'Delete'}
            </Button>
          </Space>
        ),
      },
    ];

    // Add subtitle column only for desktop view
    if (width >= 768) {
      baseColumns.splice(2, 0, {
        title: 'Subtitle',
        dataIndex: 'subtitle',
        key: 'subtitle',
        // Render with multi-line ellipsis and proper wrapping
        render: (text) => (
          <Typography.Paragraph
            ellipsis={{ rows: 2, tooltip: text }}
            style={{ marginBottom: 0, whiteSpace: 'normal', wordBreak: 'break-word' }}
          >
            {text}
          </Typography.Paragraph>
        ),
      });
    }

    return baseColumns;
  };

  return (
    <Table
      columns={getColumns()}
      dataSource={items}
      rowKey="id"
      loading={loading}
      scroll={{ x: true }}
      pagination={{
        responsive: true,
        position: width < 768 ? ['bottomCenter'] : ['bottomRight'],
        size: width < 768 ? 'small' : 'default'
      }}
      size={width < 768 ? 'small' : 'middle'}
    />
  );
});

export default SliderList;
